using UnityEngine; using UnityEngine.UI;
namespace Tormia.Ontology.Core { [DisallowMultipleComponent] public sealed class OntologyAccountWorldCreationOpenButton:MonoBehaviour { void Awake(){var b=GetComponent<Button>();if(b==null)return;b.onClick.RemoveAllListeners();b.onClick.AddListener(()=>FindAnyObjectByType<OntologyAccountFlowNavigator>()?.ShowWorldCreation());} void OnEnable(){OntologyLanguagePackService.LanguageChanged+=Localize;Localize();} void OnDisable()=>OntologyLanguagePackService.LanguageChanged-=Localize; void Localize(){var t=GetComponentInChildren<TMPro.TMP_Text>(true);if(t!=null)t.text=OntologyLanguagePackService.Text("ui.account.world_create.open","CREATE WORLD");}}}
